from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        NEG = float("-inf")
        size = 1
        while size < n:
            size *= 2

        total = [0] * (2 * size)
        pref = [NEG] * (2 * size)
        suff = [NEG] * (2 * size)
        best = [NEG] * (2 * size)

        def pull(node: int) -> None:
            left, right = node * 2, node * 2 + 1
            total[node] = total[left] + total[right]
            pref[node] = max(pref[left], total[left] + pref[right])
            suff[node] = max(suff[right], total[right] + suff[left])
            best[node] = max(best[left], best[right], suff[left] + pref[right])

        for i, x in enumerate(nums):
            node = size + i
            total[node] = x
            pref[node] = x
            suff[node] = x
            best[node] = x

        for node in range(size - 1, 0, -1):
            pull(node)

        def update(idx: int, value: int, active: bool) -> None:
            node = size + idx
            total[node] = value

            if active:
                pref[node] = value
                suff[node] = value
                best[node] = value
            else:
                pref[node] = NEG
                suff[node] = NEG
                best[node] = NEG

            node //= 2
            while node:
                pull(node)
                node //= 2

        ans = best[1]

        positions = defaultdict(list)
        for i, x in enumerate(nums):
            positions[x].append(i)

        for value, pos_list in positions.items():
            if value >= 0 or len(pos_list) == n:
                continue

            for i in pos_list:
                update(i, 0, False)

            ans = max(ans, best[1])

            for i in pos_list:
                update(i, value, True)

        return ans
